package cli

import (
	"fmt"
	"os"
	"strconv"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func configCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "config",
		Short: "Manage configuration",
	}

	cmd.AddCommand(configShowCmd())
	cmd.AddCommand(configSetCmd())
	cmd.AddCommand(configGetCmd())

	return cmd
}

func configShowCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "show",
		Short: "Show resolved configuration",
		Args:  cobra.NoArgs,
		Run: func(cmd *cobra.Command, args []string) {
			cfg := internal.LoadConfig()

			fmt.Println("# Resolved configuration (global + per-repo)")
			fmt.Printf("agent_command: %s\n", cfg.GetAgentCommand())
			if cfg.UseTmux != nil {
				fmt.Printf("use_tmux: %v\n", *cfg.UseTmux)
			} else {
				fmt.Println("use_tmux: false (default)")
			}
			if cfg.InjectInto != "" {
				fmt.Printf("inject_into: %s\n", cfg.InjectInto)
			} else {
				fmt.Println("inject_into: . (default, worktree root)")
			}
			if len(cfg.Workspaces) > 0 {
				fmt.Println("workspaces:")
				for k, v := range cfg.Workspaces {
					fmt.Printf("  %s: %s\n", k, v)
				}
			}
			fmt.Println()
			fmt.Println("# Paths")
			fmt.Printf("global: %s\n", internal.ConfigPath())
			repoPath := internal.RepoConfigPath()
			if repoPath != "" {
				fmt.Printf("repo:   %s\n", repoPath)
			}
		},
	}
}

func configSetCmd() *cobra.Command {
	var repo bool

	cmd := &cobra.Command{
		Use:   "set <key> <value>",
		Short: "Set a config value (keys: agent_command, use_tmux, inject_into)",
		Args:  cobra.ExactArgs(2),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if len(args) == 0 {
				return []string{"agent_command", "use_tmux", "inject_into"}, cobra.ShellCompDirectiveNoFileComp
			}
			if len(args) == 1 && args[0] == "agent_command" {
				return []string{"claude", "opencode", "aider", "copilot"}, cobra.ShellCompDirectiveNoFileComp
			}
			if len(args) == 1 && args[0] == "use_tmux" {
				return []string{"true", "false"}, cobra.ShellCompDirectiveNoFileComp
			}
			return nil, cobra.ShellCompDirectiveNoFileComp
		},
		Run: func(cmd *cobra.Command, args []string) {
			key, value := args[0], args[1]

			path := internal.ConfigPath()
			if repo {
				path = internal.RepoConfigPath()
				if path == "" {
					fmt.Println("Error: not inside a git repository")
					os.Exit(1)
				}
			}

			cfg := internal.LoadConfigFile(path)

			switch key {
			case "agent_command":
				cfg.AgentCommand = value
			case "use_tmux":
				b, err := strconv.ParseBool(value)
				if err != nil {
					fmt.Printf("Error: use_tmux must be true or false, got %q\n", value)
					os.Exit(1)
				}
				cfg.UseTmux = &b
			case "inject_into":
				cfg.InjectInto = value
			default:
				fmt.Printf("Unknown key: %s (valid: agent_command, use_tmux, inject_into)\n", key)
				os.Exit(1)
			}

			if err := internal.SaveConfigFile(path, cfg); err != nil {
				fmt.Printf("Error saving config: %v\n", err)
				os.Exit(1)
			}

			scope := "global"
			if repo {
				scope = "repo"
			}
			fmt.Printf("Set %s = %s (%s: %s)\n", key, value, scope, path)
		},
	}

	cmd.Flags().BoolVar(&repo, "repo", false, "Edit per-repo config instead of global")

	return cmd
}

func configGetCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "get <key>",
		Short: "Get a resolved config value",
		Args:  cobra.ExactArgs(1),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			return []string{"agent_command", "use_tmux"}, cobra.ShellCompDirectiveNoFileComp
		},
		Run: func(cmd *cobra.Command, args []string) {
			cfg := internal.LoadConfig()

			switch args[0] {
			case "agent_command":
				fmt.Println(cfg.GetAgentCommand())
			case "use_tmux":
				if cfg.UseTmux != nil {
					fmt.Println(*cfg.UseTmux)
				} else {
					fmt.Println("false")
				}
			case "inject_into":
				if cfg.InjectInto != "" {
					fmt.Println(cfg.InjectInto)
				} else {
					fmt.Println(".")
				}
			default:
				fmt.Printf("Unknown key: %s (valid: agent_command, use_tmux, inject_into)\n", args[0])
				os.Exit(1)
			}
		},
	}
}

package cli

import (
	"fmt"
	"os"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func injectCmd() *cobra.Command {
	var into string

	cmd := &cobra.Command{
		Use:   "inject <feature> [branch]",
		Short: "Sync inject/ files into worktrees",
		Long: `Re-sync shared files from inject/ into worktrees. With no branch, syncs all worktrees.

Injected files are symlinked into the worktree. By default they go to
the worktree root. Use --into to target a subdirectory (e.g., --into .context).

Set inject_into in config to change the default:
  tws config set inject_into .context
  tws config set inject_into .context --repo

Tip: To keep git status clean, either:
  - Add injected filenames to .gitignore (e.g., CLAUDE.local.md)
  - Use --into to target a gitignored subfolder (e.g., --into .context)
  - Or nest inside an already-ignored dir like inject/.claude/`,
		Args: cobra.RangeArgs(1, 2),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			switch len(args) {
			case 0:
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			case 1:
				return internal.ListBranches(args[0]), cobra.ShellCompDirectiveNoFileComp
			default:
				return nil, cobra.ShellCompDirectiveNoFileComp
			}
		},
		Run: func(cmd *cobra.Command, args []string) {
			feature := args[0]
			featurePath := internal.FeaturePath(feature)

			if _, err := os.Stat(featurePath); os.IsNotExist(err) {
				fmt.Printf("Feature not found: %s\n", feature)
				os.Exit(1)
			}

			injectDir := internal.InjectPath(featurePath)
			if _, err := os.Stat(injectDir); os.IsNotExist(err) {
				fmt.Printf("No inject/ directory found for feature: %s\n", feature)
				fmt.Printf("Create it at: %s\n", injectDir)
				os.Exit(1)
			}

			target := internal.ResolveInjectInto(into)

			if len(args) == 2 {
				branch := args[1]
				path := internal.WorktreePath(feature, branch)
				if _, err := os.Stat(path); os.IsNotExist(err) {
					fmt.Printf("Worktree not found: %s/%s\n", feature, branch)
					os.Exit(1)
				}
				if err := internal.InjectFiles(featurePath, path, target); err != nil {
					fmt.Printf("Error: %v\n", err)
					os.Exit(1)
				}
				if target != "" && target != "." {
					fmt.Printf("Injected files into: %s/%s/%s\n", feature, branch, target)
				} else {
					fmt.Printf("Injected files into: %s/%s\n", feature, branch)
				}
			} else {
				count, err := internal.InjectFilesForFeature(featurePath, target)
				if err != nil {
					fmt.Printf("Error: %v\n", err)
					os.Exit(1)
				}
				fmt.Printf("Injected files into %d worktree(s)\n", count)
			}
		},
	}

	cmd.Flags().StringVar(&into, "into", "", "Target subdirectory within worktree (default: root, or inject_into from config)")

	return cmd
}

package cli

import (
	"fmt"
	"os"
	"os/exec"
	"strings"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func newCmd() *cobra.Command {
	var base string
	var force bool

	cmd := &cobra.Command{
		Use:   "new <feature> <branch>",
		Short: "Create a worktree branch",
		Args:  cobra.ExactArgs(2),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			switch len(args) {
			case 0:
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			case 1:
				return internal.ListBranches(args[0]), cobra.ShellCompDirectiveNoFileComp
			default:
				return nil, cobra.ShellCompDirectiveNoFileComp
			}
		},
		Run: func(cmd *cobra.Command, args []string) {
			createWorktree(args[0], args[1], base, force)
		},
	}

	cmd.Flags().StringVar(&base, "base", "main", "Parent branch for stacking")
	cmd.Flags().BoolVarP(&force, "force", "f", false, "Force checkout of already checked-out branch")

	return cmd
}

// createWorktree is the shared logic for creating a worktree branch.
// Used by both tws new and tws add -n.
func createWorktree(feature, branch, base string, force bool) {
	internal.RequireTool("git")

	featurePath := internal.FeaturePath(feature)
	path := internal.WorktreePath(feature, branch)

	internal.Must(os.MkdirAll(featurePath, 0755))

	repoRoot, err := internal.MainRepoRoot()
	if err != nil {
		fmt.Println("Error: must be run from inside a git repository")
		os.Exit(1)
	}

	if internal.BranchExists(branch) {
		if isCheckedOut(branch) && !force {
			fmt.Printf("Warning: branch %q is already checked out in another worktree.\n", branch)
			fmt.Println("Use --force to check it out anyway.")
			os.Exit(1)
		}

		gitArgs := []string{"worktree", "add"}
		if force {
			gitArgs = append(gitArgs, "--force")
		}
		gitArgs = append(gitArgs, path, branch)
		internal.Must(internal.RunDir(repoRoot, "git", gitArgs...))
	} else {
		internal.Must(internal.RunDir(repoRoot, "git", "worktree", "add", path, "-b", branch))
	}

	stack, _ := internal.LoadStack(featurePath)
	if !internal.HasBranch(stack, branch) {
		stack.Branches = append(stack.Branches, internal.StackEntry{Name: branch, Base: base})
		internal.Must(internal.SaveStack(featurePath, stack))
	}

	// Inject shared files into the worktree
	target := internal.ResolveInjectInto("")
	if err := internal.InjectFiles(featurePath, path, target); err != nil {
		fmt.Printf("Warning: inject failed: %v\n", err)
	}

	fmt.Printf("Worktree created: %s (base: %s)\n", path, base)
}

// isCheckedOut checks if a branch is currently checked out in any worktree.
func isCheckedOut(branch string) bool {
	out, err := exec.Command("git", "worktree", "list", "--porcelain").Output()
	if err != nil {
		return false
	}
	for _, line := range strings.Split(string(out), "\n") {
		if strings.TrimSpace(line) == "branch refs/heads/"+branch {
			return true
		}
	}
	return false
}

package cli

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func openCmd() *cobra.Command {
	var useTmux bool
	var noTmux bool
	var noAgent bool

	cmd := &cobra.Command{
		Use:   "open [feature] [branch]",
		Short: "Open worktree and run agent",
		Long:  "Open a worktree and run the configured agent. With no args, shows an interactive picker.",
		Args:  cobra.RangeArgs(0, 2),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			switch len(args) {
			case 0:
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			case 1:
				return internal.ListBranches(args[0]), cobra.ShellCompDirectiveNoFileComp
			default:
				return nil, cobra.ShellCompDirectiveNoFileComp
			}
		},
		Run: func(cmd *cobra.Command, args []string) {
			feature, branch, err := resolveOpenArgs(args)
			if err != nil {
				fmt.Println(err)
				os.Exit(1)
			}

			path := internal.WorktreePath(feature, branch)

			if _, err := os.Stat(path); os.IsNotExist(err) {
				fmt.Printf("Worktree not found: %s\n", path)
				os.Exit(1)
			}

			// Re-sync inject files
			featurePath := internal.FeaturePath(feature)
			injectTarget := internal.ResolveInjectInto("")
			if err := internal.InjectFiles(featurePath, path, injectTarget); err != nil {
				fmt.Printf("Warning: inject sync failed: %v\n", err)
			}

			// Show unread decisions count
			unread := internal.UnreadDecisions(featurePath, branch)
			if len(unread) > 0 {
				targeted := 0
				for _, d := range unread {
					if d.To != "" {
						targeted++
					}
				}
				msg := fmt.Sprintf("  %d new decision(s)", len(unread))
				if targeted > 0 {
					msg += fmt.Sprintf(" (%d for you)", targeted)
				}
				msg += fmt.Sprintf(" (run: tws decisions show %s)", feature)
				fmt.Println(msg)
			}

			if noAgent {
				fmt.Printf("cd %s\n", path)
				fmt.Println("Run your agent manually from there.")
				return
			}

			// Resolve tmux preference
			tmux := useTmux
			if !cmd.Flags().Changed("tmux") && !noTmux {
				cfg := internal.LoadConfig()
				if cfg.UseTmux != nil {
					tmux = *cfg.UseTmux
				}
			}
			if noTmux {
				tmux = false
			}

			if tmux {
				openWithTmux(feature, branch, path)
			} else {
				// Warn if there's a stale tmux session
				session := sanitizeSessionName(feature + "/" + branch)
				if sessionExists(session) {
					fmt.Printf("Warning: tmux session %q exists for this worktree.\n", session)
					fmt.Printf("  Run 'tws close %s %s' to kill it, or use --tmux to attach.\n", feature, branch)
				}
				openDirect(path)
			}
		},
	}

	cmd.Flags().BoolVar(&useTmux, "tmux", false, "Wrap in tmux session")
	cmd.Flags().BoolVar(&noTmux, "no-tmux", false, "Skip tmux even if configured")
	cmd.Flags().BoolVar(&noAgent, "no-agent", false, "Just print the worktree path")

	return cmd
}

func resolveOpenArgs(args []string) (string, string, error) {
	var feature, branch string
	var err error

	switch len(args) {
	case 2:
		return args[0], args[1], nil
	case 1:
		feature = args[0]
		branches := internal.ListBranches(feature)
		if len(branches) == 0 {
			return "", "", fmt.Errorf("no branches found for feature: %s", feature)
		}
		branch, err = pick("Select branch:", branches)
		if err != nil {
			return "", "", err
		}
		return feature, branch, nil
	case 0:
		features := internal.ListFeatures()
		if len(features) == 0 {
			return "", "", fmt.Errorf("no features found. Use 'tws add <feature>' to create one")
		}
		feature, err = pick("Select feature:", features)
		if err != nil {
			return "", "", err
		}
		branches := internal.ListBranches(feature)
		if len(branches) == 0 {
			return "", "", fmt.Errorf("no branches found for feature: %s", feature)
		}
		branch, err = pick("Select branch:", branches)
		if err != nil {
			return "", "", err
		}
		return feature, branch, nil
	}
	return "", "", fmt.Errorf("unexpected args")
}

func openDirect(path string) {
	cfg := internal.LoadConfig()
	agentCmd := cfg.GetAgentCommand()

	if isClaudeAgent(agentCmd) && hasClaudeSession(path) {
		agentCmd = agentCmd + " -c"
	}

	parts := strings.Fields(agentCmd)
	if _, err := exec.LookPath(parts[0]); err != nil {
		fmt.Printf("Error: agent %q not found in PATH\n", parts[0])
		os.Exit(1)
	}

	fmt.Printf("Opening: %s\nRunning: %s\n", path, agentCmd)

	// Run agent as subprocess in the worktree directory
	agent := exec.Command(parts[0], parts[1:]...)
	agent.Dir = path
	agent.Stdin = os.Stdin
	agent.Stdout = os.Stdout
	agent.Stderr = os.Stderr

	if err := agent.Run(); err != nil {
		fmt.Printf("Agent exited: %v\n", err)
	}

	// Spawn an interactive shell in the worktree dir so the user stays there
	shell := os.Getenv("SHELL")
	if shell == "" {
		shell = "/bin/sh"
	}

	fmt.Printf("Dropped into shell at: %s\n", path)
	sh := exec.Command(shell)
	sh.Dir = path
	sh.Stdin = os.Stdin
	sh.Stdout = os.Stdout
	sh.Stderr = os.Stderr
	_ = sh.Run()
}

func openWithTmux(feature, branch, path string) {
	internal.RequireTool("tmux")

	session := sanitizeSessionName(feature + "/" + branch)

	if sessionExists(session) {
		fmt.Printf("Attaching to existing session: %s\n", session)
		internal.Must(internal.Run("tmux", "attach", "-t", session))
		return
	}

	cfg := internal.LoadConfig()
	agentCmd := cfg.GetAgentCommand()

	if isClaudeAgent(agentCmd) && hasClaudeSession(path) {
		agentCmd = agentCmd + " -c"
	}

	fmt.Printf("Creating tmux session: %s\n", session)
	internal.Must(internal.Run("tmux", "new-session", "-d", "-s", session, "-c", path))

	fmt.Printf("Running: %s\n", agentCmd)
	internal.Must(internal.Run("tmux", "send-keys", "-t", session, agentCmd, "Enter"))

	internal.Must(internal.Run("tmux", "attach", "-t", session))
}

func sessionExists(name string) bool {
	cmd := exec.Command("tmux", "has-session", "-t", name)
	err := cmd.Run()
	return err == nil
}

func sanitizeSessionName(s string) string {
	r := strings.NewReplacer(".", "_", ":", "_", "/", "-")
	return r.Replace(s)
}

func isClaudeAgent(cmd string) bool {
	base := strings.Fields(cmd)[0]
	return base == "claude" || base == "claude-dev" || base == "cc"
}

func hasClaudeSession(workdir string) bool {
	home, err := os.UserHomeDir()
	if err != nil {
		return false
	}

	absPath, err := filepath.Abs(workdir)
	if err != nil {
		return false
	}

	encoded := strings.ReplaceAll(absPath, string(filepath.Separator), "-")
	projectDir := filepath.Join(home, ".claude", "projects", encoded)

	info, err := os.Stat(projectDir)
	if err != nil {
		return false
	}
	return info.IsDir()
}

package cli

import (
	"fmt"
	"os"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func templateCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "template",
		Short: "Manage workspace templates",
	}

	cmd.AddCommand(templateSyncCmd())

	return cmd
}

func templateSyncCmd() *cobra.Command {
	var templates []string
	var all bool

	cmd := &cobra.Command{
		Use:   "sync [feature]",
		Short: "Apply template files to existing feature(s)",
		Long:  "Copy template files into a feature's inject/ directory. Skips existing files. Use --all to sync all features.",
		Args:  cobra.MaximumNArgs(1),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if len(args) == 0 {
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			}
			return nil, cobra.ShellCompDirectiveNoFileComp
		},
		Run: func(cmd *cobra.Command, args []string) {
			if all {
				features := internal.ListFeatures()
				if len(features) == 0 {
					fmt.Println("No features found.")
					return
				}
				for _, feature := range features {
					syncFeatureTemplate(feature, templates)
				}
				return
			}

			if len(args) == 0 {
				fmt.Println("Usage: tws template sync <feature> [--template <dir>]")
				fmt.Println("       tws template sync --all")
				os.Exit(1)
			}

			syncFeatureTemplate(args[0], templates)
		},
	}

	cmd.Flags().StringArrayVar(&templates, "template", nil, "Template directory (can be specified multiple times)")
	cmd.Flags().BoolVar(&all, "all", false, "Sync all features")

	return cmd
}

func syncFeatureTemplate(feature string, extraTemplates []string) {
	featurePath := internal.FeaturePath(feature)

	if _, err := os.Stat(featurePath); os.IsNotExist(err) {
		fmt.Printf("%s: not found\n", feature)
		return
	}

	injectDir := internal.InjectPath(featurePath)
	if err := os.MkdirAll(injectDir, 0755); err != nil {
		fmt.Printf("%s: error creating inject dir: %v\n", feature, err)
		return
	}

	fmt.Printf("%s:\n", feature)
	applyTemplates(injectDir, extraTemplates)

	// Re-sync inject into worktrees
	target := internal.ResolveInjectInto("")
	count, err := internal.InjectFilesForFeature(featurePath, target)
	if err != nil {
		fmt.Printf("  Warning: worktree inject failed: %v\n", err)
	} else if count > 0 {
		fmt.Printf("  Synced inject to %d worktree(s)\n", count)
	}
}

package internal

import (
	"os"
	"path/filepath"

	"gopkg.in/yaml.v3"
)

type Config struct {
	Workspaces   map[string]string `yaml:"workspaces"`
	AgentCommand string            `yaml:"agent_command"`
	UseTmux      *bool             `yaml:"use_tmux"`
	InjectInto   string            `yaml:"inject_into"`
}

func (c Config) GetAgentCommand() string {
	if c.AgentCommand != "" {
		return c.AgentCommand
	}
	return "claude"
}

// ConfigPath returns the global config path.
func ConfigPath() string {
	home, _ := os.UserHomeDir()
	return filepath.Join(home, ".config", "tws", "config.yaml")
}

func repoConfigPath() string {
	root, err := RepoRoot()
	if err != nil {
		return ""
	}
	return filepath.Join(root, ".tws", "config.yaml")
}

func loadConfigFile(path string) Config {
	if path == "" {
		return Config{}
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return Config{}
	}
	var cfg Config
	if err := yaml.Unmarshal(data, &cfg); err != nil {
		return Config{}
	}
	return cfg
}

// LoadConfig loads the global config, then merges per-repo config on top.
// Per-repo values override global values when set.
func LoadConfig() Config {
	cfg := loadConfigFile(ConfigPath())
	repo := loadConfigFile(repoConfigPath())

	if repo.AgentCommand != "" {
		cfg.AgentCommand = repo.AgentCommand
	}
	if repo.UseTmux != nil {
		cfg.UseTmux = repo.UseTmux
	}
	if repo.InjectInto != "" {
		cfg.InjectInto = repo.InjectInto
	}
	if len(repo.Workspaces) > 0 {
		if cfg.Workspaces == nil {
			cfg.Workspaces = make(map[string]string)
		}
		for k, v := range repo.Workspaces {
			cfg.Workspaces[k] = v
		}
	}

	return cfg
}

// SaveConfigFile writes a config to the given path.
func SaveConfigFile(path string, cfg Config) error {
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0755); err != nil {
		return err
	}
	data, err := yaml.Marshal(&cfg)
	if err != nil {
		return err
	}
	return os.WriteFile(path, data, 0644)
}

// RepoConfigPath exports the per-repo config path for the config command.
func RepoConfigPath() string {
	return repoConfigPath()
}

// LoadConfigFile loads a single config file (exported for the config command).
func LoadConfigFile(path string) Config {
	return loadConfigFile(path)
}

// TemplatePath returns the template directory path.
// Per-repo (.tws/templates/) takes priority over global (~/.config/tws/templates/).
// Returns empty string if neither exists.
func TemplatePath() string {
	// Per-repo first
	repoPath := repoConfigPath()
	if repoPath != "" {
		repoTemplates := filepath.Join(filepath.Dir(repoPath), "templates")
		if info, err := os.Stat(repoTemplates); err == nil && info.IsDir() {
			return repoTemplates
		}
	}

	// Global
	home, _ := os.UserHomeDir()
	globalTemplates := filepath.Join(home, ".config", "tws", "templates")
	if info, err := os.Stat(globalTemplates); err == nil && info.IsDir() {
		return globalTemplates
	}

	return ""
}

package internal

import (
	"fmt"
	"os"
	"path/filepath"
)

const InjectDir = "inject"

// InjectPath returns the inject directory path for a feature.
func InjectPath(featurePath string) string {
	return filepath.Join(featurePath, InjectDir)
}

// InjectFiles symlinks all files from the feature's inject/ directory
// into the target worktree. injectInto is a relative subdirectory within
// the worktree (empty string or "." means worktree root).
// Uses relative symlinks. Skips existing files.
func InjectFiles(featurePath, worktreePath, injectInto string) error {
	injectDir := InjectPath(featurePath)

	if _, err := os.Stat(injectDir); os.IsNotExist(err) {
		return nil // no inject dir, nothing to do
	}

	targetBase := worktreePath
	if injectInto != "" && injectInto != "." {
		targetBase = filepath.Join(worktreePath, injectInto)
		if err := os.MkdirAll(targetBase, 0755); err != nil {
			return fmt.Errorf("could not create inject target %s: %w", targetBase, err)
		}
	}

	return filepath.Walk(injectDir, func(srcPath string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}

		relPath, err := filepath.Rel(injectDir, srcPath)
		if err != nil {
			return err
		}

		if relPath == "." {
			return nil
		}

		destPath := filepath.Join(targetBase, relPath)

		if info.IsDir() {
			return os.MkdirAll(destPath, 0755)
		}

		if _, err := os.Lstat(destPath); err == nil {
			return nil
		}

		relTarget, err := filepath.Rel(filepath.Dir(destPath), srcPath)
		if err != nil {
			return fmt.Errorf("could not compute relative path: %w", err)
		}

		return os.Symlink(relTarget, destPath)
	})
}

// InjectFilesForFeature re-syncs inject/ into all active worktrees for a feature.
func InjectFilesForFeature(featurePath, injectInto string) (int, error) {
	wtDir := filepath.Join(featurePath, "worktrees")
	entries, err := os.ReadDir(wtDir)
	if err != nil {
		return 0, nil
	}

	count := 0
	for _, e := range entries {
		if !e.IsDir() {
			continue
		}
		wtPath := filepath.Join(wtDir, e.Name())
		if err := InjectFiles(featurePath, wtPath, injectInto); err != nil {
			fmt.Printf("  Warning: inject failed for %s: %v\n", e.Name(), err)
		} else {
			count++
		}
	}
	return count, nil
}

// ResolveInjectInto returns the inject target from the flag or config.
func ResolveInjectInto(flagValue string) string {
	if flagValue != "" {
		return flagValue
	}
	cfg := LoadConfig()
	return cfg.InjectInto
}
